), ins AS (
    INSERT INTO enrollments (student_id, cs_id, status, date_enrolled, final_percentage, final_gwa,
                             grade_components_json, retention_state, clinic_hours_completed)
    SELECT s.student_id, sc.cs_id, 'Active', v.date_enrolled::date, v.final_percentage::numeric, v.final_gwa::numeric,
           v.grade_components_json::jsonb, v.retention_state, v.clinic_hours_completed::integer
      FROM v JOIN seed_cs sc ON sc.ckey = v.ckey JOIN students s ON s.student_number = v.student_number ORDER BY v.ord
    RETURNING enrollment_id, student_id, cs_id
)
INSERT INTO seed_enr SELECT sc.ckey, s.student_number, ins.enrollment_id
  FROM ins JOIN seed_cs sc ON sc.cs_id = ins.cs_id JOIN students s ON s.student_id = ins.student_id;

