), ins AS (
    INSERT INTO attendance_sessions (cs_id, secretary_user_id, owner_user_id, session_date, session_code, room,
                                     started_at, ended_at, status, geofence_enabled, biometric_required,
                                     opening_time, present_cutoff_time, late_cutoff_time, created_at, updated_at)
    SELECT sc.cs_id, v.owner_user_id::integer, v.owner_user_id::integer, v.session_date::date, v.session_code, v.room,
           v.started_at::timestamp, v.ended_at::timestamp, 'ended', FALSE, FALSE,
           TIME '08:00', TIME '08:15', TIME '08:30', v.started_at::timestamp, v.ended_at::timestamp
      FROM v JOIN seed_cs sc ON sc.ckey = v.ckey ORDER BY v.ord
    RETURNING session_id, cs_id, session_code
)
INSERT INTO seed_sess SELECT sc.ckey, ins.session_code, ins.session_id FROM ins JOIN seed_cs sc ON sc.cs_id = ins.cs_id;

