-- 9. Cost recovery results after two failed remedial attempts
INSERT INTO enrollment_cost_recovery (enrollment_id, final_grade, outcome, actor_user_id, recorded_at)
SELECT e.enrollment_id, v.final_grade::numeric, v.outcome, v.actor::integer, v.recorded_at::timestamp
FROM (VALUES
    ('2024-2025|1ST|DENT-1B', '2024-DENT-0024', 2.25, 'passed', 5, '2025-03-17 02:00:00'),
    ('2024-2025|2ND|DMAT-2B', '2023-DENT-0026', 5.0, 'failed', 3, '2025-08-25 02:00:00'),
    ('2025-2026|1ST|DENT-1A', '2025-DENT-0001', 2.25, 'passed', 14, '2026-03-16 02:00:00')
) AS v(ckey, student_number, final_grade, outcome, actor, recorded_at)
JOIN seed_enr e ON e.ckey = v.ckey AND e.student_number = v.student_number;

-- 10. Faculty invitations (the digests match no valid token; reissue to get a working link)
INSERT INTO security_tokens (purpose, user_id, token_digest, issued_at, expires_at)
SELECT 'faculty_invitation', v.user_id::integer, sha256(convert_to('dentisys-demo-invitation-' || v.user_id, 'UTF8')),
       COALESCE(v.issued_at::timestamp, LOCALTIMESTAMP), COALESCE(v.expires_at::timestamp, LOCALTIMESTAMP + INTERVAL '7 days')
FROM (VALUES
    (7, NULL, NULL),
    (8, '2026-09-10 01:00:00', '2026-09-17 01:00:00')
) AS v(user_id, issued_at, expires_at)
JOIN user_accounts ua ON ua.user_id = v.user_id::integer AND ua.status = 'Pending Activation'
WHERE (SELECT go FROM seed_run);

-- 11. Keep identity sequences ahead of the explicit ids
DO $seq$
BEGIN
    PERFORM setval(pg_get_serial_sequence('user_accounts', 'user_id'), GREATEST((SELECT COALESCE(MAX(user_id), 1) FROM user_accounts), 1), true);
    PERFORM setval(pg_get_serial_sequence('students', 'student_id'), GREATEST((SELECT COALESCE(MAX(student_id), 1) FROM students), 1), true);
    PERFORM setval(pg_get_serial_sequence('courses', 'course_id'), GREATEST((SELECT COALESCE(MAX(course_id), 1) FROM courses), 1), true);
    PERFORM setval(pg_get_serial_sequence('class_sections', 'cs_id'), GREATEST((SELECT COALESCE(MAX(cs_id), 1) FROM class_sections), 1), true);
    PERFORM setval(pg_get_serial_sequence('enrollments', 'enrollment_id'), GREATEST((SELECT COALESCE(MAX(enrollment_id), 1) FROM enrollments), 1), true);
    PERFORM setval(pg_get_serial_sequence('assessments', 'assessment_id'), GREATEST((SELECT COALESCE(MAX(assessment_id), 1) FROM assessments), 1), true);
    PERFORM setval(pg_get_serial_sequence('assessment_scores', 'score_id'), GREATEST((SELECT COALESCE(MAX(score_id), 1) FROM assessment_scores), 1), true);
    PERFORM setval(pg_get_serial_sequence('attendance_sessions', 'session_id'), GREATEST((SELECT COALESCE(MAX(session_id), 1) FROM attendance_sessions), 1), true);
    PERFORM setval(pg_get_serial_sequence('attendance_records', 'record_id'), GREATEST((SELECT COALESCE(MAX(record_id), 1) FROM attendance_records), 1), true);
    PERFORM setval(pg_get_serial_sequence('enrollment_remedial_attempts', 'remedial_attempt_id'), GREATEST((SELECT COALESCE(MAX(remedial_attempt_id), 1) FROM enrollment_remedial_attempts), 1), true);
    PERFORM setval(pg_get_serial_sequence('security_tokens', 'token_id'), GREATEST((SELECT COALESCE(MAX(token_id), 1) FROM security_tokens), 1), true);
END
$seq$;

COMMIT;
